c.cpp:
class Solution {
public:
    vector<int> maxSumDistinct(vector<int>& nums, int k) {
        set<int, greater<int>> s(nums.begin(), nums.end());
        vector<int> res;
        for (int x : s) {
            if ((int)res.size() == k) break;
            res.push_back(x);
        }
        return res;
    }
};

c.java:
class Solution {
    public int[] maxSumDistinct(int[] nums, int k) {
        TreeSet<Integer> s = new TreeSet<>(Collections.reverseOrder());
        for (int x : nums) s.add(x);
        int m = Math.min(k, s.size());
        int[] res = new int[m];
        int i = 0;
        for (int x : s) {
            if (i == m) break;
            res[i++] = x;
        }
        return res;
    }
}

